INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2638505', 'Franco-Hova Wars', 'The Franco-Hova Wars, also known as the Franco-Malagasy Wars, were two French military interventions in Madagascar between 1883 and 1896 that overthrew the ruling monarchy of the Merina Kingdom, and resulted in Madagascar becoming a French colony. The term "Hova" referred to a social class within the Merina class structure.', 1895, 9, NULL, NULL, NULL, NULL, 'month', 'September 1895', 50, 'https://en.wikipedia.org/wiki/Franco-Hova_Wars'),
  ('Q3305728', 'Menalamba Rebellion', 'The Menalamba rebellion was an uprising in Madagascar by the Merina people that emerged in central Madagascar in response to the French capture of the royal palace in the capital city of Antananarivo in September 1895. It spread rapidly in 1896, threatening the capital, but French forces were successful in securing the surrender of many rebel groups in 1897.', 1895, NULL, NULL, 1904, NULL, NULL, 'year', '1895–1904', 41, 'https://en.wikipedia.org/wiki/Menalamba_rebellion'),
  ('Q134700781', 'Sadiavahy Rebellion', 'The Sadiavahy rebellion was anti-colonial uprisings that broke out in southern and western Madagascar between 1915–1917. These revolts, though smaller than the Menalamba rebellion, expressed widespread resistance to the French colonial system, particularly its heavy taxation, forced labour and suppression of free speech and dissent.', 1915, NULL, NULL, 1917, NULL, NULL, 'year', '1915–1917', 26, 'https://en.wikipedia.org/wiki/Sadiavahy_Rebellion'),
  ('Q1052651', 'Battle of Madagascar', 'The Battle of Madagascar (5 May – 6 November 1942) was an Allied campaign to capture the Vichy French−controlled island Madagascar during World War II. The seizure of the island by the British was to deny Madagascar''s ports to the Imperial Japanese Navy and to prevent the loss or impairment of the Allied shipping routes to India, Australia and Southeast Asia. It began with Operation Ironclad, the seizure of the port of Diego-Suarez (now Antsiranana) near the northern tip of the island, on 5 May 1942.', 1942, 5, 5, 1942, 11, 6, 'day', '5 May 1942 – 6 November 1942', 66, 'https://en.wikipedia.org/wiki/Battle_of_Madagascar'),
  ('Q2506639', 'Malagasy Uprising', 'The Malagasy Uprising (French: Insurrection malgache; Malagasy: Tolom-bahoaka tamin'' ny 1947) was a Malagasy nationalist rebellion against French colonial rule in Madagascar, lasting from March 1947 to February 1949. Starting in late 1945, Madagascar''s first French National Assembly deputies, Joseph Raseta, Joseph Ravoahangy, and Jacques Rabemananjara of the Mouvement démocratique de la rénovation malgache (MDRM) political party, led an effort to achieve independence for Madagascar through legal channels.', 1947, 3, NULL, 1949, 2, NULL, 'month', 'March 1947 – February 1949', 57, 'https://en.wikipedia.org/wiki/Malagasy_Uprising'),
  ('Q17107768', 'Rotaka', 'The rotaka was a series of farmer and student protests in Madagascar between April 1971 and May 1972 that led to the collapse of the First Republic of Madagascar under President Philibert Tsiranana.', 1971, NULL, NULL, 1972, NULL, NULL, 'year', '1971–1972', 34, 'https://en.wikipedia.org/wiki/Rotaka'),
  ('Q130754', '2004 Indian Ocean earthquake', 'On 26 December 2004, at 07:58:53 local time (UTC+7), a Mw 9.2–9.3 earthquake struck with its epicenter off the west coast of Aceh, in northern Sumatra, Indonesia. The undersea megathrust earthquake, known in the scientific community as the Sumatra–Andaman earthquake, was caused by a rupture along the fault boundary between the Burma plate and the Indian plate, and reached a maximum Mercalli intensity of IX in some areas.', 2004, 12, 26, NULL, NULL, NULL, 'day', '26 December 2004', 85, 'https://en.wikipedia.org/wiki/2004_Indian_Ocean_earthquake_and_tsunami'),
  ('Q18890069', '2015 Southeast Africa floods', 'The 2015 Southeast Africa floods, partially related to Cyclone Bansi and Tropical Storm Chedza, killed at least 176 people in Malawi, 86 in Mozambique, and at least 46 in Madagascar over the course of a week while leaving hundreds more missing. Vice President of Malawi Saulos Chilima stated that over 200,000 Malawian people have been displaced by the flood.', 2015, NULL, NULL, NULL, NULL, NULL, 'year', '2015', 43, 'https://en.wikipedia.org/wiki/2015_Southeast_Africa_floods'),
  ('Q118316106', '2023 Africa floods', 'From February to late-December 2023, floods killed over 2,600 people in 15 countries across Africa.', 2023, 2, 5, NULL, NULL, NULL, 'day', '5 February 2023', 43, 'https://en.wikipedia.org/wiki/2023_Africa_floods'),
  ('Q136377386', '2025 Malagasy protests', 'The 2025 Malagasy protests were decentralized, Gen Z–led protests across Madagascar from September to October 2025, culminating in a coup d''état by the CAPSAT unit, which overthrew sitting President Andry Rajoelina and led to the establishment of the Council of the Presidency for the Re-Foundation of the Republic. The protests were triggered by frequent water and power outages in the capital city Antananarivo, and spread across Madagascar.', 2025, 9, 25, 2025, 10, 14, 'day', '25 September 2025 – 14 October 2025', 50, 'https://en.wikipedia.org/wiki/2025_Malagasy_protests'),
  ('Q136487699', '2025 Malagasy coup d''état', 'On 12 October 2025, CAPSAT, an elite unit of the Madagascar Armed Forces, overthrew the government of President Andry Rajoelina, the culmination of a protest movement which began in late September. The unit urged the rest of the military to join them and the capital Antananarivo was seized with little resistance.', 2025, 10, 12, 2025, 10, 14, 'day', '12 October 2025 – 14 October 2025', 52, 'https://en.wikipedia.org/wiki/2025_Malagasy_coup_d''%C3%A9tat');

